CREATE TABLE `Checkout` (
 `id` VARCHAR(191) NOT NULL,`customerId` VARCHAR(191) NOT NULL,`requestKey` VARCHAR(191) NOT NULL,`fingerprint` VARCHAR(191) NOT NULL,
 `subtotal` INTEGER NOT NULL,`originalDelivery` INTEGER NOT NULL,`delivery` INTEGER NOT NULL,`total` INTEGER NOT NULL,`area` JSON NOT NULL,`address` JSON NOT NULL,`version` INTEGER NOT NULL DEFAULT 1,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
 PRIMARY KEY(`id`),UNIQUE INDEX `Checkout_customerId_requestKey_key`(`customerId`,`requestKey`),
 CONSTRAINT `Checkout_customerId_fkey` FOREIGN KEY(`customerId`) REFERENCES `User`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
ALTER TABLE `Order` ADD COLUMN `checkoutId` VARCHAR(191) NULL, ADD COLUMN `deliveryStartedAt` DATETIME(3) NULL, ADD COLUMN `deliveryStartedBy` VARCHAR(191) NULL, ADD COLUMN `settlementFrozen` BOOLEAN NOT NULL DEFAULT false,
 ADD CONSTRAINT `Order_checkoutId_fkey` FOREIGN KEY (`checkoutId`) REFERENCES `Checkout`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE `FinancialAudit` (`id` VARCHAR(191) NOT NULL,`checkoutId` VARCHAR(191) NOT NULL,`actorId` VARCHAR(191) NOT NULL,`action` VARCHAR(191) NOT NULL,`before` JSON NOT NULL,`after` JSON NOT NULL,`reason` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(`id`),CONSTRAINT `FinancialAudit_checkoutId_fkey` FOREIGN KEY(`checkoutId`) REFERENCES `Checkout`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `ShippingEntry` (`id` VARCHAR(191) NOT NULL,`orderId` VARCHAR(191) NOT NULL,`amount` INTEGER NOT NULL,`kind` VARCHAR(191) NOT NULL,`reference` VARCHAR(191) NOT NULL,`actorId` VARCHAR(191) NOT NULL,`note` VARCHAR(191) NOT NULL,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(`id`),UNIQUE INDEX `ShippingEntry_reference_key`(`reference`),CONSTRAINT `ShippingEntry_orderId_fkey` FOREIGN KEY(`orderId`) REFERENCES `Order`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE TABLE `CancellationReview` (`id` VARCHAR(191) NOT NULL,`orderId` VARCHAR(191) NOT NULL,`reason` VARCHAR(191) NOT NULL,`requestedBy` VARCHAR(191) NOT NULL,`state` VARCHAR(191) NOT NULL DEFAULT 'PENDING',`decisionReason` VARCHAR(191) NOT NULL DEFAULT '',`decidedBy` VARCHAR(191) NULL,`decidedAt` DATETIME(3) NULL,`shippingRetained` INTEGER NULL,`refundDue` INTEGER NOT NULL DEFAULT 0,`createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(`id`),INDEX `CancellationReview_state_createdAt_idx`(`state`,`createdAt`),CONSTRAINT `CancellationReview_orderId_fkey` FOREIGN KEY(`orderId`) REFERENCES `Order`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
